// src/components/JobItem.jsx
import React, { useState } from "react";
import axios from "axios";
import "./JobItem.css";

const JobItem = ({ job, onJobUpdated, onJobDeleted }) => {
  const [editing, setEditing] = useState(false);
  const [newStatus, setNewStatus] = useState(job.status);

  const handleDelete = async () => {
    try {
      await axios.delete(`http://localhost:5000/api/jobs/${job._id}`);
      onJobDeleted();
    } catch (err) {
      console.error(err);
    }
  };

  const handleUpdate = async () => {
    try {
      await axios.put(`http://localhost:5000/api/jobs/${job._id}`, { ...job, status: newStatus });
      setEditing(false);
      onJobUpdated();
    } catch (err) {
      console.error(err);
    }
  };

  return (
    <div className="job-item">
      <div className="job-header">
        <h3>{job.company}</h3>
        <i className="job-role">{job.role}</i>
      </div>
      <p><strong>Date:</strong> {new Date(job.date).toLocaleDateString()}</p>
      <p><strong>Status:</strong> 
        <span className={`status-badge ${job.status.toLowerCase()}`}>{job.status}</span>
      </p>
      <p>
        <strong>Link:</strong>{" "}
        <a href={job.link} target="_blank" rel="noopener noreferrer">
          View Job Application
        </a>
      </p>

      {editing ? (
        <div className="edit-section">
          <select value={newStatus} onChange={(e) => setNewStatus(e.target.value)}>
            <option value="Applied">Applied</option>
            <option value="Interview">Interview</option>
            <option value="Offer">Offer</option>
            <option value="Rejected">Rejected</option>
          </select>
          <button className="save-btn" onClick={handleUpdate}>Save</button>
          <button className="cancel-btn" onClick={() => setEditing(false)}>Cancel</button>
        </div>
      ) : (
        <div className="button-group">
          <button className="update-btn" onClick={() => setEditing(true)}>Update</button>
          <button className="delete-btn" onClick={handleDelete}>Delete</button>
        </div>
      )}
    </div>
  );
};

export default JobItem;
